function getMonitoringPanelTemplate(panel = null) {
  const schedule = isElectricalPanelAsset(panel) ? getElectricalPanelSchedule(panel) : {};
  const count = normalizePanelCircuitCount(schedule.circuitCount || 42);
  return {
    ...MONITORING_PANEL_TEMPLATES["panel-c-42"],
    circuitCount: count || 42
  };
}

function monitoringTemplateCircuitPosition(template, circuitNumber) {
  const number = Number(circuitNumber);
  const side = number % 2 === 0 ? "right" : "left";
  const rowIndex = Math.floor((number - 1) / 2);
  const sideRows = template.rows[side] || template.rows.left;
  return {
    side,
    y: sideRows.startY + rowIndex * sideRows.rowStep,
    height: template.zones[side].row.height
  };
}

function monitoringOverlayStyle(zone = {}, y = 0, height = 2.6) {
  const zoneHeight = zone.height || height;
  return `left:${zone.x}%;top:${y}%;width:${zone.width}%;height:${zoneHeight}%;`;
}

function monitoringOverlayInnerStyle(rowZone = {}, zone = {}, height = 100) {
  const rowX = Number(rowZone.x || 0);
  const rowWidth = Math.max(1, Number(rowZone.width || 100));
  const left = ((Number(zone.x || 0) - rowX) / rowWidth) * 100;
  const top = Number(zone.y || 0);
  const width = (Number(zone.width || 0) / rowWidth) * 100;
  const zoneHeight = zone.height || height;
  return `left:${left}%;top:${top}%;width:${width}%;height:${zoneHeight}%;`;
}

function monitoringCircuitValue(channel = null, names = []) {
  for (const name of names) {
    const value = channel?.[name] ?? channel?.data?.[name] ?? channel?.telemetry?.[name] ?? channel?.latestTelemetry?.[name];
    if (value !== undefined && value !== null && String(value).trim() !== "") return String(value).trim();
  }
  return "";
}

function monitoringBreakerConfirmation(channel = null) {
  const value = channel?.data?.breakerConfirmation || {};
  return value && typeof value === "object" ? value : {};
}

function monitoringDisplayState(channel = null) {
  const liveState = String(channel?.lastDerivedState || channel?.last_derived_state || "not-monitored").toLowerCase();
  if (liveState === "energized") return "energized";
  if (liveState === "confirmed-off" || liveState === "confirmed-trip") return liveState;
  const confirmedState = String(monitoringBreakerConfirmation(channel).state || "").toLowerCase();
  if (liveState === "open" || liveState === "suspected-trip") {
    if (confirmedState === "off") return "confirmed-off";
    if (confirmedState === "tripped") return "confirmed-trip";
  }
  return liveState;
}

function monitoringDisplayLabel(channel = null) {
  const stateValue = monitoringDisplayState(channel);
  if (stateValue === "confirmed-off") return "Confirmed off";
  if (stateValue === "confirmed-trip") return "Confirmed trip";
  if (stateValue === "open") return "Needs check";
  return monitoringStateLabel(stateValue);
}

function needsBreakerConfirmation(channel = null) {
  const stateValue = monitoringDisplayState(channel);
  return stateValue === "open" || stateValue === "suspected-trip";
}

async function confirmMonitoringBreaker(channelId = "", confirmationState = "") {
  const channel = getMonitoringChannel(channelId);
  if (!channel) return;
  const state = confirmationState === "tripped" ? "tripped" : "off";
  channel.data = channel.data && typeof channel.data === "object" ? channel.data : {};
  channel.data.breakerConfirmation = {
    state,
    confirmedAt: new Date().toISOString(),
    confirmedBy: getCurrentUserLabel()
  };
  channel.updatedAt = new Date().toISOString();
  if (state === "off") {
    resolveMonitoringAlertsForChannel(channel.id, `Circuit ${channel.circuitNumber || ""} confirmed off.`);
  } else {
    const device = getMonitoringDevice(channel.deviceId || channel.device_id || "");
    if (device) ensureMonitoringAlert(device, channel);
    addActivity("Breaker trip confirmed", `Circuit ${channel.circuitNumber || ""}`);
  }
  saveStateQuietly();
  render();
  showMonitoringBreakerDetail(channel.id, channel.circuitNumber || "");
  await updateBreakerNotificationForConfirmation(channel, state);
}

function preserveMonitoringBreakerConfirmation(existing = null, incoming = null) {
  const incomingState = String(incoming?.lastDerivedState || incoming?.last_derived_state || "").toLowerCase();
  if (!["open", "suspected-trip"].includes(incomingState)) return incoming?.data || {};
  const existingConfirmation = existing?.data?.breakerConfirmation;
  if (!existingConfirmation) return incoming?.data || {};
  const confirmedAtMs = existingConfirmation.confirmedAt ? new Date(existingConfirmation.confirmedAt).getTime() : 0;
  const incomingUpdatedAtMs = incoming?.updatedAt || incoming?.updated_at ? new Date(incoming.updatedAt || incoming.updated_at).getTime() : 0;
  if (incomingUpdatedAtMs && confirmedAtMs && incomingUpdatedAtMs > confirmedAtMs + 1000) {
    const nextData = { ...(incoming?.data || {}) };
    delete nextData.breakerConfirmation;
    return nextData;
  }
  return {
    ...(incoming?.data || {}),
    breakerConfirmation: incoming?.data?.breakerConfirmation || existingConfirmation
  };
}

function positionMonitoringBreakerDrawer(anchorElement = null) {
  const elements = monitoringElements();
  const detail = elements.breakerDetail;
  if (!detail) return;
  const circuitSelectorValue = window.CSS?.escape
    ? CSS.escape(String(selectedMonitoringBreakerCircuit || ""))
    : String(selectedMonitoringBreakerCircuit || "").replace(/"/g, '\\"');
  const anchor = anchorElement || document.querySelector(`[data-monitoring-breaker-circuit="${circuitSelectorValue}"]`);
  if (!anchor) {
    detail.classList.remove("is-floating");
    detail.style.removeProperty("--breaker-detail-left");
    detail.style.removeProperty("--breaker-detail-top");
    return;
  }
  const rect = anchor.getBoundingClientRect();
  const drawerWidth = Math.min(360, Math.max(280, window.innerWidth - 24));
  const drawerHeight = Math.min(460, Math.max(260, window.innerHeight - 24));
  const gap = 12;
  const openRight = rect.right + gap + drawerWidth <= window.innerWidth - 12;
  const left = openRight
    ? rect.right + gap
    : Math.max(12, rect.left - drawerWidth - gap);
  const top = Math.min(
    Math.max(12, rect.top - 16),
    Math.max(12, window.innerHeight - drawerHeight - 12)
  );
  detail.classList.add("is-floating");
  detail.style.setProperty("--breaker-detail-left", `${Math.round(left)}px`);
  detail.style.setProperty("--breaker-detail-top", `${Math.round(top)}px`);
}

function showMonitoringBreakerDetail(channelId = "", circuitNumber = "", anchorElement = null) {
  const elements = monitoringElements();
  if (!elements.breakerDetail) return;
  selectedMonitoringBreakerChannelId = channelId || selectedMonitoringBreakerChannelId;
  selectedMonitoringBreakerCircuit = circuitNumber || selectedMonitoringBreakerCircuit;
  const channel = getMonitoringChannel(channelId);
  const panel = getAsset(channel?.panelAssetId || selectedMonitoringPanelId);
  const device = channel ? getMonitoringDevice(channel.deviceId) : null;
  const circuit = circuitNumber || channel?.circuitNumber || "";
  const label = monitoringPanelCircuitLabel(panel, circuitNumber) || "No panel label saved";
  const breakerSize = monitoringPanelCircuitBreakerSize(panel, circuitNumber) || "Not entered";
  const voltage = monitoringCircuitValue(channel, ["voltage", "lineVoltage", "line_voltage"]) || "Not reported";
  const current = monitoringCircuitValue(channel, ["current", "amps", "amperage", "loadCurrent", "load_current"]) || "Not reported";
  const temperature = monitoringCircuitValue(channel, ["temperature", "temp", "temperatureF", "temperature_f"]) || "Not reported";
  const power = monitoringCircuitValue(channel, ["kw", "kW", "power", "powerKw", "power_kw"]) || "Not reported";
  const status = channel ? monitoringDisplayLabel(channel) : "Not monitored";
  const liveStatus = channel ? monitoringStateLabel(channel.lastDerivedState || channel.last_derived_state) : "Not monitored";
  const confirmation = monitoringBreakerConfirmation(channel);
  const confirmationText = confirmation.state
    ? `${confirmation.state === "tripped" ? "Confirmed tripped" : "Confirmed off"} by ${confirmation.confirmedBy || "unknown"}${confirmation.confirmedAt ? ` on ${formatDateTime(confirmation.confirmedAt)}` : ""}`
    : "Not confirmed yet";
  const confirmActions = channel ? `
    <div class="monitoring-breaker-confirm-actions">
      <button type="button" class="secondary mini" data-monitoring-confirm-breaker="${escapeAttribute(channel.id)}" data-confirm-state="off">Confirm Off</button>
      <button type="button" class="secondary mini warn-action" data-monitoring-confirm-breaker="${escapeAttribute(channel.id)}" data-confirm-state="tripped">Confirm Tripped</button>
    </div>
  ` : "";
  elements.breakerDetail.classList.remove("hidden");
  elements.breakerDetail.innerHTML = `
    <div>
      <span>Circuit ${escapeHtml(circuit)}</span>
      <strong>${escapeHtml(status)}</strong>
      <small>${escapeHtml(label)}</small>
    </div>
    <dl>
      <div><dt>Panel</dt><dd>${escapeHtml(panel?.name || "Panel")}</dd></div>
      <div><dt>Breaker size</dt><dd>${escapeHtml(breakerSize)}</dd></div>
      <div><dt>Phase</dt><dd>${escapeHtml(channel ? monitoringChannelPhaseLabel(channel) : "Not mapped")}</dd></div>
      <div><dt>Physical channel</dt><dd>${escapeHtml(channel?.physicalChannel || "Not mapped")}</dd></div>
      <div><dt>Voltage</dt><dd>${escapeHtml(voltage)}</dd></div>
      <div><dt>Current</dt><dd>${escapeHtml(current)}</dd></div>
      <div><dt>Power</dt><dd>${escapeHtml(power)}</dd></div>
      <div><dt>Temperature</dt><dd>${escapeHtml(temperature)}</dd></div>
      <div><dt>Device</dt><dd>${escapeHtml(device?.name || "No monitor")}</dd></div>
      <div><dt>Last update</dt><dd>${escapeHtml(channel?.updatedAt ? formatDateTime(channel.updatedAt) : "Not monitored")}</dd></div>
      <div><dt>Live input</dt><dd>${escapeHtml(liveStatus)}</dd></div>
      <div><dt>Verification</dt><dd>${escapeHtml(confirmationText)}</dd></div>
    </dl>
    ${confirmActions}
  `;
  positionMonitoringBreakerDrawer(anchorElement);
}

function closeMonitoringBreakerDetail() {
  selectedMonitoringBreakerChannelId = "";
  selectedMonitoringBreakerCircuit = "";
  const detail = monitoringElements().breakerDetail;
  detail?.classList.add("hidden");
  detail?.classList.remove("is-floating");
  detail?.style.removeProperty("--breaker-detail-left");
  detail?.style.removeProperty("--breaker-detail-top");
}

function syncMonitoringPhaseSelectors() {
  const elements = monitoringElements();
  const poleCount = Math.max(1, Number(elements.channelPoles?.value || 1));
  elements.channelPhase2Wrap?.classList.toggle("hidden", poleCount < 2);
  elements.channelPhase3Wrap?.classList.toggle("hidden", poleCount < 3);
  if (elements.channelPhase2) elements.channelPhase2.disabled = poleCount < 2;
  if (elements.channelPhase3) elements.channelPhase3.disabled = poleCount < 3;
}

function monitoringStateLabel(stateValue) {
  const labels = {
    energized: "Energized",
    open: "Open",
    "confirmed-off": "Confirmed off",
    "confirmed-trip": "Confirmed trip",
    "suspected-trip": "Suspected trip",
    "upstream-power-loss": "Upstream phase loss",
    "monitoring-offline": "Monitoring offline",
    "maintenance-mode": "Maintenance mode",
    disabled: "Disabled"
  };
  return labels[stateValue] || "Unknown";
}

function monitoringStatusClass(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, "-");
}

async function hashMonitoringApiKey(apiKey) {
  const value = String(apiKey || "").trim();
  if (!value) return "";
  if (!window.crypto?.subtle) throw new Error("Secure browser crypto is required before saving an API key.");
  const data = new TextEncoder().encode(value);
  const hashBuffer = await window.crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(hashBuffer)).map(byte => byte.toString(16).padStart(2, "0")).join("");
}

function generateMonitoringApiKey() {
  const bytes = new Uint8Array(24);
  if (window.crypto?.getRandomValues) {
    window.crypto.getRandomValues(bytes);
  } else {
    bytes.forEach((_, index) => { bytes[index] = Math.floor(Math.random() * 256); });
  }
  return `swm_${Array.from(bytes).map(byte => byte.toString(16).padStart(2, "0")).join("")}`;
}

function generateLightingApiKey() {
  return generateMonitoringApiKey().replace(/^swm_/, "swl_");
}

function getLightingApiKeyFormId(form = null) {
  const editId = String(form?.dataset?.lightingControllerEditForm || "").trim();
  if (editId) return `edit:${editId}`;
  const scopeKey = getLightingControllerScopeKey?.() || `${selectedCustomerId || ""}:${selectedLocationId || ""}`;
  return `new:${scopeKey}`;
}

function readPendingLightingApiKey() {
  if (pendingLightingApiKey?.key) return pendingLightingApiKey;
  try {
    const saved = JSON.parse(sessionStorage.getItem(LIGHTING_PENDING_API_KEY_STORAGE_KEY) || "null");
    if (saved?.key) {
      pendingLightingApiKey = saved;
      return saved;
    }
  } catch {
    pendingLightingApiKey = null;
  }
  return null;
}

function savePendingLightingApiKey(form, key) {
  pendingLightingApiKey = {
    formId: getLightingApiKeyFormId(form),
    key: String(key || ""),
    savedAt: new Date().toISOString()
  };
  try {
    sessionStorage.setItem(LIGHTING_PENDING_API_KEY_STORAGE_KEY, JSON.stringify(pendingLightingApiKey));
  } catch {
    // Session storage is only a convenience; the password field still carries the key.
  }
}

function clearPendingLightingApiKey(form = null) {
  const current = readPendingLightingApiKey();
  const formId = form ? getLightingApiKeyFormId(form) : "";
  if (formId && current?.formId && current.formId !== formId) return;
  pendingLightingApiKey = null;
  try {
    sessionStorage.removeItem(LIGHTING_PENDING_API_KEY_STORAGE_KEY);
  } catch {
    // Nothing else to clean up.
  }
}

function applyPendingLightingApiKeyToForm(form = null) {
  if (!form) return;
  const pending = readPendingLightingApiKey();
  if (!pending?.key || pending.formId !== getLightingApiKeyFormId(form)) return;
  const input = form.querySelector("input[name='apiKey']");
  const output = form.querySelector("[data-lighting-generated-key]");
  const status = form.querySelector("[data-lighting-generated-key-status]");
  const copyButton = form.querySelector("[data-lighting-copy-key]");
  const generateButton = form.querySelector("[data-lighting-generate-key]");
  if (input && !input.value) input.value = pending.key;
  if (output && !output.value) output.value = pending.key;
  if (status) status.textContent = "Generated key restored from this browser session. Copy it before saving.";
  if (copyButton) copyButton.disabled = false;
  if (generateButton) generateButton.textContent = "Generate New API Key";
}

function restorePendingLightingApiKeyForms() {
  document.querySelectorAll("[data-lighting-controller-form], [data-lighting-controller-edit-form]").forEach((form) => {
    applyPendingLightingApiKeyToForm(form);
  });
}

function generatePumpApiKey() {
  return generateMonitoringApiKey().replace(/^swm_/, "swp_");
}

function generateHvacApiKey() {
  return generateMonitoringApiKey().replace(/^swm_/, "swh_");
}

function getPumpApiKeyFormId(form = null) {
  const editId = String(form?.dataset?.pumpControllerForm || "").trim();
  const scopeKey = getPumpControllerScopeKey?.() || `${selectedCustomerId || ""}:${selectedLocationId || ""}`;
  return editId ? `edit:${editId}` : `new:${scopeKey}`;
}

function readPendingPumpApiKey() {
  if (pendingPumpApiKey?.key) return pendingPumpApiKey;
  try {
    const saved = JSON.parse(sessionStorage.getItem(PUMP_PENDING_API_KEY_STORAGE_KEY) || "null");
    if (saved?.key) {
      pendingPumpApiKey = saved;
      return saved;
    }
  } catch {
    pendingPumpApiKey = null;
  }
  return null;
}

function savePendingPumpApiKey(form, key) {
  pendingPumpApiKey = {
    formId: getPumpApiKeyFormId(form),
    key: String(key || ""),
    savedAt: new Date().toISOString()
  };
  try {
    sessionStorage.setItem(PUMP_PENDING_API_KEY_STORAGE_KEY, JSON.stringify(pendingPumpApiKey));
  } catch {
    // Session storage is a convenience; the password input still carries the key.
  }
}

function clearPendingPumpApiKey(form = null) {
  const current = readPendingPumpApiKey();
  const formId = form ? getPumpApiKeyFormId(form) : "";
  if (formId && current?.formId && current.formId !== formId) return;
  pendingPumpApiKey = null;
  try {
    sessionStorage.removeItem(PUMP_PENDING_API_KEY_STORAGE_KEY);
  } catch {
    // Nothing else to clean up.
  }
}

function applyPendingPumpApiKeyToForm(form = null) {
  if (!form) return;
  const pending = readPendingPumpApiKey();
  if (!pending?.key || pending.formId !== getPumpApiKeyFormId(form)) return;
  const input = form.querySelector("input[name='apiKey']");
  const output = form.querySelector("[data-pump-generated-key]");
  const status = form.querySelector("[data-pump-generated-key-status]");
  const copyButton = form.querySelector("[data-pump-copy-key]");
  const generateButton = form.querySelector("[data-pump-generate-key]");
  if (input && !input.value) input.value = pending.key;
  if (output && !output.value) output.value = pending.key;
  if (status) status.textContent = "Generated key restored from this browser session. Copy it before saving.";
  if (copyButton) copyButton.disabled = false;
  if (generateButton) generateButton.textContent = "Generate New API Key";
}

function restorePendingPumpApiKeyForms() {
  document.querySelectorAll("[data-pump-controller-form]").forEach((form) => {
    applyPendingPumpApiKeyToForm(form);
  });
}

function getHvacApiKeyFormId(form = null) {
  const editId = String(form?.dataset?.hvacControllerForm || "").trim();
  const scopeKey = getHvacControllerScopeKey?.() || `${selectedCustomerId || ""}:${selectedLocationId || ""}`;
  return editId ? `edit:${editId}` : `new:${scopeKey}`;
}

function readPendingHvacApiKey() {
  if (pendingHvacApiKey?.key) return pendingHvacApiKey;
  try {
    const saved = JSON.parse(sessionStorage.getItem(HVAC_PENDING_API_KEY_STORAGE_KEY) || "null");
    if (saved?.key) {
      pendingHvacApiKey = saved;
      return saved;
    }
  } catch {
    pendingHvacApiKey = null;
  }
  return null;
}

