async function handleLoginSubmit(event = null) {
  event?.preventDefault();
  if (els.loginSubmitBtn?.disabled) return;
  try {
    if (els.loginSubmitBtn) els.loginSubmitBtn.disabled = true;
    suppressStorageFullWarning = true;
    setQrLoginTrace("Signing in...");
    await new Promise((resolve) => window.requestAnimationFrame(resolve));
    lastAuthError = "";
    const isQrLogin = isScannedItemUrl();
    const user = await runWithTimeout(
      signInWithSiteWorks(els.loginUsername.value, els.loginPassword.value, { fastProfileFallback: isQrLogin }),
      isQrLogin ? 20000 : 12000,
      null
    );
    if (!user && !lastAuthError) {
      lastAuthError = "Login timed out. Check the phone connection and try again.";
    }

    if (!user) {
      if (siteworksServerEnabled()) {
        setQrLoginTrace(lastAuthError || "Could not reach the SiteWorks server. Log in again when the connection is available.");
        suppressStorageFullWarning = false;
        if (els.loginSubmitBtn) els.loginSubmitBtn.disabled = false;
        return;
      }
      const localUser = findUserForLogin(els.loginUsername.value, els.loginPassword.value);
      if (!localUser) {
        setQrLoginTrace(lastAuthError || "Login did not finish. Check the connection and try again.");
        suppressStorageFullWarning = false;
        if (els.loginSubmitBtn) els.loginSubmitBtn.disabled = false;
        return;
      }
      currentUser = localUser;
      currentRole = localUser.role;
      state.currentUserId = localUser.id;
      rememberAdminUserSwitcher(localUser);
      recordUserLoginActivity(localUser, isQrLogin ? "QR login" : "Login screen");
      if (isQrLogin) {
        finishQrLoginWithoutBlocking(localUser);
        return;
      }
      els.loginError.textContent = "Opening scanned item...";
      await runWithTimeout(openScannedAssetAfterLogin(), 5000);
      saveStateQuietly();
      els.loginForm.reset();
      els.loginError.textContent = "";
      render();
      showLoginGreeting(localUser);
    window.setTimeout(() => {
      suppressStorageFullWarning = false;
      if (els.loginSubmitBtn) els.loginSubmitBtn.disabled = false;
    }, 1500);
    return;
    }

    currentUser = user;
    currentRole = user.role;
    state.currentUserId = user.id;
    rememberAdminUserSwitcher(user);
    recordUserLoginActivity(user, isQrLogin ? "QR login" : "Login screen");
    setQrLoginTrace(`Signed in as ${user.username || user.name || "SiteWorks user"}.`);
    if (isQrLogin) {
      finishQrLoginWithoutBlocking(user);
      return;
    }
    els.loginError.textContent = "Loading SiteWorks data...";
    await runWithTimeout(bootstrapCloudData(), 7000);
    await runWithTimeout(openScannedAssetAfterLogin(), 5000);
    saveStateQuietly();
    els.loginForm.reset();
    els.loginError.textContent = "";
    render();
    showLoginGreeting(user);
    window.setTimeout(() => {
      suppressStorageFullWarning = false;
      if (els.loginSubmitBtn) els.loginSubmitBtn.disabled = false;
    }, 1500);
  } catch (error) {
    console.warn("Login submit failed.", error);
    setQrLoginTrace(`Login stopped: ${error?.message || "Unknown error"}`);
    suppressStorageFullWarning = false;
    if (els.loginSubmitBtn) els.loginSubmitBtn.disabled = false;
  }
}

els.loginForm.addEventListener("submit", handleLoginSubmit);

els.forgotPasswordBtn?.addEventListener("click", () => {
  const email = String(els.loginUsername.value || "").trim().toLowerCase();
  if (!isEmailAddress(email)) {
    setQrLoginTrace("Enter your email, then ask an Admin or Manager to reset your SiteWorks password.");
    return;
  }
  setQrLoginTrace(`Ask an Admin or Manager to reset the SiteWorks password for ${email}.`);
});

els.passwordResetForm?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const password = els.resetPassword.value;
  const confirmPassword = els.resetPasswordConfirm.value;
  if (!password.trim() || password !== confirmPassword) {
    els.resetPasswordMessage.textContent = "Enter matching passwords.";
    return;
  }
  els.resetPasswordSubmitBtn.disabled = true;
  els.resetPasswordMessage.textContent = "Saving new password...";
  const result = await updateRecoveredPassword(password);
  els.resetPasswordSubmitBtn.disabled = false;
  if (!result.ok) {
    els.resetPasswordMessage.textContent = result.message || "Password could not be updated.";
    return;
  }
  els.resetPasswordMessage.textContent = "Password updated. You can log in now.";
  els.passwordResetForm.reset();
  passwordRecoveryMode = false;
  els.passwordResetForm.classList.add("hidden");
  els.loginForm.classList.remove("hidden");
  clearAuthSession();
  history.replaceState(null, "", location.pathname + location.search);
});

els.refreshCloudUsersBtn?.addEventListener("click", async () => {
  if (!canManageUsers()) return;
  els.cloudUsersStatus.textContent = "Checking server users...";
  els.cloudUsersStatus.classList.remove("is-error");
  els.cloudUsersStatus.classList.remove("is-ok");
  const result = await loadSiteWorksProfiles({ renderAfter: true });
  if (!result.ok) {
    els.cloudUsersStatus.textContent = result.message || "Could not load server users.";
    els.cloudUsersStatus.classList.add("is-error");
    return;
  }
  els.cloudUsersStatus.textContent = `Loaded ${result.cloudCount} server user${result.cloudCount === 1 ? "" : "s"}. Showing ${visibleManagedUsers().length} user${visibleManagedUsers().length === 1 ? "" : "s"} for your access.`;
  els.cloudUsersStatus.classList.add("is-ok");
});

function setQrLoginTrace(message) {
  if (!els.loginError) return;
  const prefix = isScannedItemUrl() ? `QR ${SITEWORKS_APP_VERSION}: ` : "";
  els.loginError.textContent = `${prefix}${message}`;
}

function finishQrLoginWithoutBlocking(user) {
  try {
    currentUser = user;
    currentRole = user.role || "Customer";
    state.currentUserId = user.id;
    rememberAdminUserSwitcher(user);
    upsertLocalUser(user);
    setQrLoginTrace("Login accepted. Opening scanned item...");
    persistLocalStateOnly(false);
    const params = scannedQrParams();
    params.set("qr", "1");
    params.set("refresh", SITEWORKS_APP_VERSION);
    params.set("signedin", String(Date.now()));
    window.location.replace(`${location.pathname}?${params.toString()}`);
  } catch (error) {
    console.warn("QR login open failed.", error);
    setQrLoginTrace(`QR open stopped: ${error?.message || "Unknown error"}`);
    suppressStorageFullWarning = false;
    if (els.loginSubmitBtn) els.loginSubmitBtn.disabled = false;
  }
}

function recordUserLoginActivity(user, source = "Login screen") {
  if (!user) return;
  addActivity("User logged in", `${source}.`);
}

function showLoginGreeting(user) {
  if (!els.loginGreetingToast || !user) return;
  const name = user.name || user.username || "there";
  const role = user.role || "SiteWorks user";
  els.loginGreetingToast.innerHTML = `
    <strong>Welcome, ${escapeHtml(name)}</strong>
    <span>${escapeHtml(role)}</span>
  `;
  els.loginGreetingToast.classList.remove("hidden");
  window.clearTimeout(showLoginGreeting.timer);
  showLoginGreeting.timer = window.setTimeout(() => {
    els.loginGreetingToast?.classList.add("hidden");
  }, 4200);
}

function runWithTimeout(promise, timeoutMs, timeoutValue = false) {
  return Promise.race([
    promise.catch((error) => {
      console.warn("Login follow-up step skipped.", error);
      return timeoutValue;
    }),
    new Promise((resolve) => window.setTimeout(() => resolve(timeoutValue), timeoutMs))
  ]);
}

function passwordRecoverySessionFromUrl() {
  const hashText = String(location.hash || "").replace(/^#/, "");
  if (!hashText) return null;
  const params = new URLSearchParams(hashText);
  if (params.get("type") !== "recovery" || !params.get("access_token")) return null;
  return {
    access_token: params.get("access_token"),
    refresh_token: params.get("refresh_token") || "",
    token_type: params.get("token_type") || "bearer",
    expires_in: Number(params.get("expires_in") || 0),
    expires_at: Number(params.get("expires_at") || 0),
    user: {}
  };
}

function initPasswordRecoveryFromUrl() {
  const session = passwordRecoverySessionFromUrl();
  if (!session) return;
  passwordRecoveryMode = false;
  clearAuthSession();
  history.replaceState(null, "", location.pathname + location.search);
  if (els.loginError) els.loginError.textContent = "Password reset links are no longer used. Ask an Admin or Manager to reset your SiteWorks password.";
}

async function updateRecoveredPassword(password) {
  return { ok: false, message: "Password reset links are no longer used. Ask an Admin or Manager to reset your SiteWorks password." };
}

async function openScannedAssetAfterLogin() {
  let openedScannedAsset = focusScannedAssetContext() || focusScannedInventoryContext() || focusScannedKeyContext();
  if (!openedScannedAsset && isScannedItemUrl()) {
    await runWithTimeout(refreshCloudDataFromServer(), 5000);
    openedScannedAsset = focusScannedAssetContext() || focusScannedInventoryContext() || focusScannedKeyContext();
  }
  if (!openedScannedAsset) notifyUnassignedShortNfcTag();
  if (!openedScannedAsset) closeAssetRegisterDrawer();
  return openedScannedAsset;
}

els.firstAdminForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (hasSetupUsers()) return;
  const email = els.firstAdminUsername.value.trim().toLowerCase();
  const name = els.firstAdminName.value.trim() || email;
  const password = els.firstAdminPassword.value;
  if (!email || !password.trim()) {
    els.firstAdminMessage.textContent = "Enter an email and password.";
    return;
  }
  els.firstAdminMessage.textContent = "Creating admin...";
  const user = await createSiteWorksUser(email, password, name, "Admin", "");
  if (!user) {
    if (lastAuthError.toLowerCase().includes("already")) {
      els.firstAdminMessage.textContent = "That email already exists in SiteWorks. Use the Log In form once and SiteWorks will attach the first Admin profile.";
      return;
    }
    els.firstAdminMessage.textContent = lastAuthError || "Could not create admin. If email confirmation is on, confirm the email and then log in.";
    return;
  }
  saveAuthSession(user.session);
  currentUser = user;
  currentRole = user.role;
  state.currentUserId = user.id;
  upsertLocalUser(user);
  rememberAdminUserSwitcher(user);
  closeAssetRegisterDrawer();
  addActivity("First admin created", email);
  saveStateQuietly();
  els.firstAdminForm.reset();
  els.firstAdminMessage.textContent = "";
  render();
});

