document.addEventListener("toggle", (event) => {
  const hvacDrawer = event.target.closest?.(".hvac-drawer");
  if (hvacDrawer) {
    updateHvacFirmwareAutoRefresh();
  }

  const pumpScadaDrawer = event.target.closest?.("[data-pump-scada-drawer]");
  if (pumpScadaDrawer) {
    const drawerKey = pumpScadaDrawer.dataset.pumpScadaDrawer || "";
    if (!drawerKey) return;
    touchedPumpScadaDrawers.add(drawerKey);
    if (pumpScadaDrawer.open) {
      openPumpScadaDrawers.add(drawerKey);
    } else {
      openPumpScadaDrawers.delete(drawerKey);
    }
    return;
  }
  const zoneDetails = event.target.closest?.("[data-lighting-zone-details]");
  if (zoneDetails) {
    const zoneId = zoneDetails.dataset.lightingZoneDetails || "";
    if (!zoneId) return;
    if (zoneDetails.open) {
      openLightingZoneDetails.add(zoneId);
    } else {
      openLightingZoneDetails.delete(zoneId);
    }
    return;
  }
  const diagnostics = event.target.closest?.("[data-lighting-controller-diagnostics]");
  if (!diagnostics) return;
  const controllerId = diagnostics.dataset.lightingControllerDiagnostics || "";
  if (!controllerId) return;
  if (diagnostics.open) {
    openLightingControllerDiagnostics.add(controllerId);
  } else {
    openLightingControllerDiagnostics.delete(controllerId);
  }
}, true);

