els.keyForm?.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (!canManageKeys()) return;
  const keyName = els.keyName.value.trim();
  const customerId = currentRole === "Admin" ? els.keyCustomer.value : currentUser?.customerId || selectedCustomerId || "";
  const locationId = els.keyLocation?.value || "";
  if (!keyName) {
    alert("Enter a key name.");
    return;
  }
  if (!canManageKeyCustomer(customerId)) {
    alert("Managers can only add keys for their assigned customer.");
    return;
  }
  const shouldWriteNfcTag = Boolean(els.keyWriteAfterSave?.checked && !els.keyWriteAfterSave?.disabled);
  const now = new Date().toISOString();
  const key = {
    id: crypto.randomUUID(),
    customerId,
    locationId,
    uniqueTagId: normalizeNfcUid(els.keyTagUid.value) || els.keyTagUid.value.trim(),
    additionalTagUids: normalizeKeyExtraTagUids(els.keyAdditionalTagUids?.value || ""),
    keyName,
    keyNumber: els.keyNumber.value.trim(),
    storageLocation: els.keyStorageLocation.value.trim(),
    currentStatus: "Available",
    currentHolderId: "",
    currentHolderName: "",
    defaultCheckoutHours: DEFAULT_KEY_CHECKOUT_HOURS,
    dueBackAt: "",
    notes: els.keyNotes.value.trim(),
    createdAt: now,
    updatedAt: now
  };
  state.keys.push(key);
  addKeyLog(key, "Check-In", "Key record created.");
  addActivity("Key added", key.keyName);
  saveState();
  await syncSingleKeyToServer(key);
  if (shouldWriteNfcTag) {
    if (els.keyStatus) {
      els.keyStatus.textContent = "Key saved. Writing NFC tag...";
      els.keyStatus.className = "inline-status";
    }
    await writeKeyNfcTag(key);
  }
  els.keyForm.reset();
  keyWizardStep = 0;
  renderKeySetupWizard();
  if (els.keyStatus) {
    const nfcWriteFailed = shouldWriteNfcTag && String(key.nfcMessage || "").toLowerCase().includes("failed");
    els.keyStatus.textContent = shouldWriteNfcTag
      ? `Added ${key.keyName}. NFC write ${nfcWriteFailed ? "needs attention" : "complete"}.`
      : `Added ${key.keyName}.`;
    els.keyStatus.className = nfcWriteFailed ? "inline-status is-error" : "inline-status is-ok";
  }
  closeTopActionDrawers();
  showCreationConfirmation(`Key created: ${key.keyName}`);
  render();
});

els.keySetupWizard?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-key-wizard-target]");
  if (!button) return;
  event.preventDefault();
  setKeyWizardStep(Number(button.dataset.keyWizardTarget || 0));
});

els.keyForm?.addEventListener("click", (event) => {
  const scanNfcButton = event.target.closest("[data-key-wizard-scan-nfc]");
  if (scanNfcButton) {
    event.preventDefault();
    scanKeyWizardNfcTag(scanNfcButton);
    return;
  }

  const nextButton = event.target.closest("[data-key-wizard-next]");
  if (nextButton) {
    event.preventDefault();
    if (!validateKeyWizardStep(keyWizardStep)) return;
    setKeyWizardStep(keyWizardStep + 1);
    return;
  }
  const prevButton = event.target.closest("[data-key-wizard-prev]");
  if (prevButton) {
    event.preventDefault();
    setKeyWizardStep(keyWizardStep - 1);
  }
});

els.keyForm?.addEventListener("input", () => {
  renderKeySetupWizard();
});

function startKeySetupWizard(slotNumber = "") {
  keyWizardStep = 0;
  if (slotNumber && els.keyNumber && !els.keyNumber.value.trim()) {
    els.keyNumber.value = slotNumber;
  }
  if (els.keyStatus) {
    els.keyStatus.textContent = "";
    els.keyStatus.className = "inline-status";
  }
  renderKeySetupWizard();
}

function setKeyWizardStep(step) {
  keyWizardStep = Math.min(Math.max(Number.isInteger(step) ? step : 0, 0), 4);
  renderKeySetupWizard();
  window.setTimeout(() => getKeyWizardFocusTarget()?.focus(), 30);
}

function renderKeySetupWizard() {
  els.keySetupWizard?.querySelectorAll("[data-key-wizard-target]").forEach((button) => {
    const step = Number(button.dataset.keyWizardTarget || 0);
    button.classList.toggle("is-active", step === keyWizardStep);
    button.classList.toggle("is-complete", step < keyWizardStep);
  });
  els.keyForm?.querySelectorAll("[data-key-wizard-panel]").forEach((panel) => {
    panel.classList.toggle("is-active", Number(panel.dataset.keyWizardPanel || 0) === keyWizardStep);
  });
  const prevButton = els.keyForm?.querySelector("[data-key-wizard-prev]");
  const nextButton = els.keyForm?.querySelector("[data-key-wizard-next]");
  if (prevButton) prevButton.disabled = keyWizardStep <= 0;
  if (nextButton) {
    nextButton.classList.toggle("hidden", keyWizardStep >= 4);
    nextButton.textContent = keyWizardStep === 3 ? "Review" : "Next";
  }
  if (els.keyWizardReview) {
    els.keyWizardReview.textContent = buildKeyWizardReviewText();
  }
  if (els.keyWriteAfterSave) {
    const canWriteFromThisDevice = canUseLocalNfcBridge();
    els.keyWriteAfterSave.disabled = !canWriteFromThisDevice;
    els.keyWriteAfterSave.closest("label")?.classList.toggle("is-disabled", !canWriteFromThisDevice);
  }
}

function validateKeyWizardStep(step) {
  if (step === 1 && !els.keyName?.value.trim()) {
    if (els.keyStatus) {
      els.keyStatus.textContent = "Enter a key name before continuing.";
      els.keyStatus.className = "inline-status is-error";
    }
    els.keyName?.focus();
    return false;
  }
  if (els.keyStatus) {
    els.keyStatus.textContent = "";
    els.keyStatus.className = "inline-status";
  }
  return true;
}

function getKeyWizardFocusTarget() {
  if (keyWizardStep === 0) return els.keyTagUid;
  if (keyWizardStep === 1) return els.keyName;
  if (keyWizardStep === 2) return els.keyLocation || els.keyCustomer;
  if (keyWizardStep === 3) return els.keyNotes;
  return els.keyForm?.querySelector("button[type='submit']");
}

function buildKeyWizardReviewText() {
  const parts = [
    els.keyTagUid?.value.trim() ? `NFC ${els.keyTagUid.value.trim()}` : "No NFC tag yet",
    els.keyName?.value.trim() || "Unnamed key",
    els.keyLocation?.selectedOptions?.[0]?.textContent || "All locations",
    els.keyNotes?.value.trim() ? "Notes added" : "No notes"
  ];
  return parts.join(" | ");
}

async function scanKeyWizardNfcTag(button = null) {
  if (!canUseLocalNfcBridge()) {
    if (els.keyStatus) {
      els.keyStatus.textContent = "NFC scanning is available from a desktop browser connected to the local ACR122U bridge.";
      els.keyStatus.className = "inline-status is-error";
    }
    return;
  }
  if (button) button.disabled = true;
  if (els.keyStatus) {
    els.keyStatus.textContent = "Hold the NFC tag on the ACR122U reader...";
    els.keyStatus.className = "inline-status";
  }
  try {
    const result = await callNfcBridgeWithFallback(["/nfc/read", "/nfc/verify"], {
      expectedUid: "",
      expectedUrl: "",
      recordType: "key-setup"
    });
    const uid = normalizeNfcUid(getNfcResponseUid(result));
    if (!uid) throw new Error("The NFC bridge did not return a tag UID.");
    const existingKey = findKeyByNfcUid(uid);
    if (existingKey) {
      throw new Error(`Tag UID ${uid} is already assigned to ${existingKey.keyName || existingKey.name || "another key"}.`);
    }
    if (els.keyTagUid) els.keyTagUid.value = uid;
    if (els.keyStatus) {
      els.keyStatus.textContent = `Scanned NFC tag ${uid}.`;
      els.keyStatus.className = "inline-status is-ok";
    }
    renderKeySetupWizard();
  } catch (error) {
    console.warn("Key setup NFC scan failed.", error);
    if (els.keyStatus) {
      els.keyStatus.textContent = `NFC scan failed: ${error.message || "Bridge unavailable."}`;
      els.keyStatus.className = "inline-status is-error";
    }
  } finally {
    if (button) button.disabled = false;
  }
}

