document.addEventListener("click", async (event) => {
  if (event.target.closest("#serverHealthRefreshBtn")) {
    event.preventDefault();
    await loadServerHealth();
    return;
  }

  if (event.target.closest("[data-hvac-firmware-refresh]")) {
    event.preventDefault();
    setHvacFirmwareStatus("Refreshing HVAC firmware status...");
    await loadHvacFirmwareForCurrentScope({ force: true, firmwareOnly: true });
    return;
  }

  const openNotification = event.target.closest("[data-notification-open]");
  if (openNotification) {
    event.preventDefault();
    openServerNotification(openNotification.dataset.notificationOpen);
    return;
  }

  const ackNotification = event.target.closest("[data-notification-ack]");
  if (ackNotification) {
    event.preventDefault();
    acknowledgeServerNotification(ackNotification.dataset.notificationAck);
    return;
  }

  const resolveNotification = event.target.closest("[data-notification-resolve]");
  if (resolveNotification) {
    event.preventDefault();
    resolveServerNotification(resolveNotification.dataset.notificationResolve);
    return;
  }

  if (!event.target.closest("#notificationCenterWrap")) closeNotificationCenter();

  if (event.target.closest("[data-monitoring-close-breaker-detail]")) {
    event.preventDefault();
    closeMonitoringBreakerDetail();
    return;
  }

  const confirmBreaker = event.target.closest("[data-monitoring-confirm-breaker]");
  if (confirmBreaker) {
    event.preventDefault();
    await confirmMonitoringBreaker(confirmBreaker.dataset.monitoringConfirmBreaker, confirmBreaker.dataset.confirmState);
    return;
  }

  const breakerDetail = event.target.closest("[data-monitoring-breaker-detail]");
  if (breakerDetail) {
    event.preventDefault();
    const breakerChannel = getMonitoringChannel(breakerDetail.dataset.monitoringBreakerDetail || "");
    const breakerDevice = breakerChannel ? getMonitoringDevice(breakerChannel.deviceId || breakerChannel.device_id || "") : null;
    if (isDemoMonitoringDevice(breakerDevice)) {
      cycleDemoMonitoringBreaker(breakerChannel);
      return;
    }
    selectedMonitoringBreakerChannelId = breakerDetail.dataset.monitoringBreakerDetail || "";
    selectedMonitoringBreakerCircuit = breakerDetail.dataset.monitoringBreakerCircuit || "";
    showMonitoringBreakerDetail(breakerDetail.dataset.monitoringBreakerDetail, breakerDetail.dataset.monitoringBreakerCircuit, breakerDetail);
    return;
  }

  const openBreakerDetail = monitoringElements().breakerDetail;
  if (
    openBreakerDetail &&
    !openBreakerDetail.classList.contains("hidden") &&
    openBreakerDetail.classList.contains("is-floating") &&
    !event.target.closest("#monitoringBreakerDetail")
  ) {
    closeMonitoringBreakerDetail();
  }

  const openPanelAsset = event.target.closest("[data-open-asset]");
  if (openPanelAsset) {
    const asset = getAsset(openPanelAsset.dataset.openAsset);
    if (asset) {
      selectedId = asset.id;
      openPanel("assetPanel");
      render();
    }
    return;
  }
  const editDevice = event.target.closest("[data-monitoring-edit-device]");
  if (editDevice) {
    loadMonitoringDeviceForm(editDevice.dataset.monitoringEditDevice);
    return;
  }
  const editChannel = event.target.closest("[data-monitoring-edit-channel]");
  if (editChannel) {
    loadMonitoringChannelForm(editChannel.dataset.monitoringEditChannel);
    return;
  }
  const deleteDevice = event.target.closest("[data-monitoring-delete-device]");
  if (deleteDevice) {
    deleteMonitoringDevice(deleteDevice.dataset.monitoringDeleteDevice);
    return;
  }
  if (event.target.closest("#monitoringRotateKeyBtn")) {
    rotateMonitoringDeviceKey();
    return;
  }
  if (event.target.closest("#monitoringRepairKeyBtn")) {
    repairMonitoringCloudKey();
    return;
  }
  const deleteChannel = event.target.closest("[data-monitoring-delete-channel]");
  if (deleteChannel) {
    deleteMonitoringChannel(deleteChannel.dataset.monitoringDeleteChannel);
    return;
  }
  const acknowledgeAlert = event.target.closest("[data-monitoring-ack]");
  if (acknowledgeAlert) {
    updateMonitoringAlertStatus(acknowledgeAlert.dataset.monitoringAck, "acknowledged");
    return;
  }
  const resolveAlert = event.target.closest("[data-monitoring-resolve]");
  if (resolveAlert) {
    updateMonitoringAlertStatus(resolveAlert.dataset.monitoringResolve, "resolved");
    return;
  }
  const createTicket = event.target.closest("[data-monitoring-work-order]");
  if (createTicket) {
    createMonitoringWorkOrder(createTicket.dataset.monitoringWorkOrder);
  }
});

document.addEventListener("change", (event) => {
  const target = event.target;
  if (!(target instanceof HTMLElement)) return;
  if (target.id === "monitoringChannelDevice" || target.id === "monitoringSimulatorDevice") {
    renderMonitoringIfReady();
  }
  if (target.id === "monitoringChannelCircuit" || target.id === "monitoringChannelCircuitManual") {
    applyMonitoringCircuitScheduleDefaults();
  }
  if (target.id === "monitoringChannelPoles") {
    syncMonitoringPhaseSelectors();
  }
  if (target.id === "monitoringPanelSelect") {
    selectedMonitoringPanelId = target.value || "";
    renderMonitoringIfReady();
  }
});

// Panel Monitor functions now live in /js/panel-monitor.js.
// Keep this boundary so future panel monitor work stays out of the main app file.

function renderSiteMapIfReady() {
  if (typeof renderSiteMap === "function") renderSiteMap();
}

async function refreshSiteMapMonitorMode() {
  if (!siteMapMonitorMode || !isPanelVisiblyOpen("siteMapPanel")) return;
  await Promise.allSettled([
    refreshCloudDataFromServer(),
    syncMonitoringStatusFromApi(),
    loadServerNotifications()
  ]);
  renderSiteMapIfReady();
}

function renderMonitoringIfReady() {
  if (typeof renderMonitoring === "function") renderMonitoring();
}

function render() {
  if (!requireServerSessionForApp()) return;
  renderAuth();
  if (isPublicKeyUrl()) {
    renderPublicKeyScan();
    return;
  }
  if (isPublicReportUrl()) {
    renderPublicReport();
    return;
  }
  if (!currentUser) return;
  resetInactivityLogoutTimer();
  restoreScannedAssetSelection();
  restoreScannedInventorySelection();
  syncPublicReportsFromServer();
  ensureSelection();
  renderUsers();
  renderPreferredContractors();
  renderAccessRequests();
  renderActivityLog();
  renderTemplates();
  renderCustomers();
  renderLocations();
  renderCustomerOptions();
  renderTemplateOptions();
  renderLocationOptions();
  renderAssetLocationOptions();
  renderDashboard();
  renderAutomationPumps();
  renderSiteMapIfReady();
  renderMonitoringIfReady();
  renderPmCalendar();
  renderBackupStatus();
  renderSyncHealth();
  renderQrSettings();
  renderAssetTableControls();
  renderAssetTable();
  renderWorkOrders();
  renderServiceRequests();
  renderInventory();
  renderKeys();
  setInventoryTab(inventoryTab);
  syncWorkDrawerBackdrop();
  renderServiceRequestFormOptions();
  renderNewIssueFormOptions();
  renderCompletedPms();
  renderPanelToggles();

  const asset = getSelectedAsset();
  els.customerCount.textContent = canSeeAllCustomers()
    ? `${state.customers.length} total`
    : manageableSetupCustomers().length;
  els.templateCount.textContent = visibleTemplatesForCurrentView().length;
  els.locationCount.textContent = state.locations.filter((locationRecord) =>
    manageableSetupCustomers().some((customer) => customer.id === locationRecord.customerId)
  ).length;
  els.assetCount.textContent = filteredAssets().length;
  els.emptyState.innerHTML = "";
  els.emptyState.classList.toggle("hidden", true);
  els.assetPanel.classList.toggle("hidden", !asset);
  positionAssetPanelNearSelection(asset);
  renderPanelToggles();
  renderRole();

  if (!asset) return;

  const customer = getCustomer(asset.customerId);
  const locationRecord = getLocation(asset.locationId);
  const template = getTemplate(asset.templateId);
  const due = getDueInfo(asset);
  els.selectedLocation.textContent = `${customer?.name || "Unknown customer"} | ${locationRecord?.name || "Unknown location"}`;
  els.selectedName.textContent = asset.name;
  els.selectedMeta.textContent = `Equipment ID ${getAssetEquipmentId(asset)} | Every ${asset.frequencyDays} days`;
  els.selectedBadges.innerHTML = renderAssetBadges(asset, due);
  els.selectedAssetThumb.innerHTML = renderAssetThumbnail(asset);
  els.selectedTemplate.textContent = template?.name || "Template missing";
  els.selectedQr.innerHTML = `<img alt="QR code for ${escapeHtml(asset.name)}" src="${qrUrl(getAssetUrl(asset.id))}">`;
  els.nextPm.textContent = formatDate(due.nextDate);
  els.nextPmInput.value = asset.nextPmDate || toDateInputValue(due.nextDate);
  els.clearNextPmBtn.disabled = !asset.nextPmDate || !canManageWorkOrders();
  els.pmStatus.textContent = due.label;
  els.pmStatus.className = due.className;
  els.assetPhotoPanel.innerHTML = renderAssetPhoto(asset);
  els.assetManualPanel.innerHTML = renderAssetManual(asset);
  els.assetDetailsGrid.innerHTML = renderAssetDetails(asset);
  if (els.assetNfcPanel) els.assetNfcPanel.innerHTML = renderAssetNfcPanel(asset);
  renderElectricalPanelSchedule(asset);
  if (els.deleteSelectedAssetBtn) {
    els.deleteSelectedAssetBtn.classList.toggle("hidden", !canDeleteEquipment());
    els.deleteSelectedAssetBtn.disabled = !canDeleteEquipment();
  }
  renderAssetInfoForm(asset);
  renderChecklist(template, asset);
  renderAssetWorkOrders(asset);
  renderAssetGallery(asset);
  renderRole();

  if (els.historyCount) els.historyCount.textContent = asset.history.length;
  els.historyList.innerHTML = asset.history.length
    ? asset.history.map(renderHistoryItem).join("")
    : `<p class="muted">No completed maintenance yet.</p>`;
}

function renderAuth() {
  const isReport = isPublicReportUrl();
  const isPublicKey = isPublicKeyUrl();
  const isLoggedIn = Boolean(currentUser);
  const hasScannedAsset = Boolean(getAssetIdFromUrl());
  const needsFirstAdmin = !isReport && !isPublicKey && !isLoggedIn && !hasSetupUsers();
  els.publicKeyScreen?.classList.toggle("hidden", !isPublicKey);
  els.publicReportScreen.classList.toggle("hidden", !isReport);
  els.loginScreen.classList.toggle("hidden", isReport || isPublicKey || isLoggedIn);
  els.loginForm.classList.toggle("hidden", passwordRecoveryMode);
  els.passwordResetForm?.classList.toggle("hidden", !passwordRecoveryMode);
  els.loginQrReportPrompt.classList.toggle("hidden", passwordRecoveryMode || isReport || isPublicKey || isLoggedIn || !hasScannedAsset);
  els.userSwitcherWrap?.classList.add("hidden");
  if (!isReport && !isPublicKey && !isLoggedIn && hasScannedAsset) {
    setLoginQrReportStatus(Boolean(getScannedReportAsset()));
    if (!els.loginError.textContent.trim()) setQrLoginTrace("QR ready. Log in to open equipment.");
  }
  syncLoginQrReportPrompt();
  els.firstAdminForm.classList.add("hidden");
  els.appOnly.forEach((node) => node.classList.toggle("hidden", isReport || isPublicKey || !isLoggedIn));
  if (isReport || isPublicKey || !isLoggedIn) return;
  els.currentUserName.textContent = currentUser.name || currentUser.username;
  els.currentUserRole.textContent = currentUser.role;
  renderUserSwitcher();
}

function closeAssetRegisterDrawer() {
  if (!els.assetRegisterDrawer) return;
  els.assetRegisterDrawer.open = false;
  if (els.assetRegisterDrawer.classList.contains("sidebar-controlled-panel")) {
    els.assetRegisterDrawer.classList.add("hidden");
  }
  delete els.assetRegisterDrawer.dataset.openedByMetric;
  setSidebarTargetButtonState("assetRegisterDrawer", false);
}

function openAssetRegisterDrawer(openedByMetric = "") {
  if (!els.assetRegisterDrawer) return;
  if (openedByMetric) els.assetRegisterDrawer.dataset.openedByMetric = openedByMetric;
  els.assetRegisterDrawer.classList.remove("hidden");
  els.assetRegisterDrawer.open = true;
  setSidebarTargetButtonState("assetRegisterDrawer", true);
}

function toggleAssetRegisterDrawer() {
  if (!els.assetRegisterDrawer) return;
  const isOpen = els.assetRegisterDrawer.open && !els.assetRegisterDrawer.classList.contains("hidden");
  if (isOpen) closeAssetRegisterDrawer();
  else openAssetRegisterDrawer();
}

function togglePanel(panelId) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  const wasCollapsed = panel.classList.contains("is-collapsed");
  const willCollapse = !wasCollapsed;
  panel.classList.toggle("is-collapsed");
  if (panel.classList.contains("sidebar-controlled-panel")) {
    panel.classList.toggle("hidden", willCollapse);
    setSidebarTargetButtonState(panelId, !willCollapse);
  }
  if (panelId === "assetPanel" && wasCollapsed) closeSelectedAssetDrawers();
  renderPanelToggles();
  syncCalendarFocusState();
}

function openPanel(panelId) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  const wasCollapsed = panel.classList.contains("is-collapsed");
  panel.classList.remove("hidden");
  panel.classList.remove("is-collapsed");
  if (panel.classList.contains("sidebar-controlled-panel")) setSidebarTargetButtonState(panelId, true);
  if (panelId === "assetPanel" && wasCollapsed) closeSelectedAssetDrawers();
  renderPanelToggles();
  syncCalendarFocusState();
}

function setSidebarTargetButtonState(targetId, isOpen) {
  document.querySelectorAll("[data-open-target]").forEach((button) => {
    if (button.dataset.openTarget !== targetId) return;
    button.classList.toggle("is-active", isOpen);
    button.setAttribute("aria-expanded", String(isOpen));
    const hint = button.querySelector(".sidebar-nav-hint");
    if (hint) hint.textContent = isOpen ? "Close" : "Open";
  });
}

function closeSidebarTarget(targetId) {
  const target = document.getElementById(targetId);
  if (!target) return;
  const wasSiteMapOpen = targetId === "siteMapPanel" && isPanelVisiblyOpen("siteMapPanel");
  if (targetId === "assetRegisterDrawer" && els.assetPanel?.classList.contains("floating-asset-panel")) {
    els.assetPanel.classList.add("hidden");
    els.assetPanel.classList.remove("floating-asset-panel", "is-collapsed");
    els.assetPanel.style.top = "";
  }
  if (target.tagName === "DETAILS") {
    target.open = false;
    if (target.classList.contains("sidebar-controlled-panel")) target.classList.add("hidden");
  }
  if (target.classList.contains("collapsible-panel")) {
    target.classList.add("is-collapsed");
    target.classList.add("hidden");
    renderPanelToggles();
  }
  setSidebarTargetButtonState(targetId, false);
  if (targetId === "inventoryPanel") syncInventorySidebarMenuState();
  if (isAutomationTargetId(targetId)) syncAutomationSidebarMenuState();
  if (targetId === "pmCalendarPanel" || targetId === "templatesPanel") syncPmSidebarMenuState();
  syncCalendarFocusState();
  if (wasSiteMapOpen) restoreMobileDashboardAfterSiteMapClose();
}

function openSidebarTarget(targetId) {
  const target = document.getElementById(targetId);
  if (!target) return;

  const isOpen = target.tagName === "DETAILS"
    ? target.open && !target.classList.contains("hidden")
    : target.classList.contains("collapsible-panel")
      && !target.classList.contains("hidden")
      && !target.classList.contains("is-collapsed");

  if (isOpen) {
    closeSidebarTarget(targetId);
    return;
  }

  closeOtherSidebarTargets(targetId);

  if (target.tagName === "DETAILS") {
    target.classList.remove("hidden");
    target.open = true;
  }
  if (target.classList.contains("collapsible-panel")) {
    target.classList.remove("hidden");
    openPanel(targetId);
  }
  setSidebarTargetButtonState(targetId, true);
  if (targetId === "inventoryPanel") syncInventorySidebarMenuState();
  if (isAutomationTargetId(targetId)) syncAutomationSidebarMenuState();
  if (targetId === "pmCalendarPanel" || targetId === "templatesPanel") syncPmSidebarMenuState();
  syncCalendarFocusState();
}

function automationTargetIds() {
  return [
    "monitoringPanel",
    "automationHvacPanel",
    "automationLightingPanel",
    "automationPumpsPanel",
    "automationEnergyPanel",
    "automationGeneratorPanel"
  ];
}

function isAutomationTargetId(targetId = "") {
  return automationTargetIds().includes(targetId);
}

function closeAllSidebarTargets() {
  document.querySelectorAll("[data-open-target]").forEach((button) => {
    closeSidebarTarget(button.dataset.openTarget);
  });
  closeSidebarTarget("pmCalendarPanel");
  closeSidebarTarget("templatesPanel");
  closeSidebarTarget("siteMapPanel");
  automationTargetIds().forEach(closeSidebarTarget);
  closeSidebarTarget("inventoryPanel");
}

function closeOtherSidebarTargets(activeTargetId) {
  document.querySelectorAll("[data-open-target]").forEach((button) => {
    if (button.dataset.openTarget !== activeTargetId) {
      closeSidebarTarget(button.dataset.openTarget);
    }
  });
  if (activeTargetId !== "pmCalendarPanel") closeSidebarTarget("pmCalendarPanel");
  if (activeTargetId !== "templatesPanel") closeSidebarTarget("templatesPanel");
  if (activeTargetId !== "siteMapPanel") closeSidebarTarget("siteMapPanel");
  automationTargetIds().forEach((targetId) => {
    if (activeTargetId !== targetId) closeSidebarTarget(targetId);
  });
  if (activeTargetId !== "inventoryPanel") closeSidebarTarget("inventoryPanel");
}

function syncCalendarFocusState() {
  const calendarOpen = isPanelVisiblyOpen("pmCalendarPanel");
  const siteMapOpen = isPanelVisiblyOpen("siteMapPanel");
  if (!siteMapOpen) {
    siteMapFullScreen = false;
    siteMapMonitorMode = false;
  }
  const siteMapFullScreenActive = Boolean((siteMapFullScreen || siteMapMonitorMode) && siteMapOpen);
  const siteMapMonitorActive = Boolean(siteMapMonitorMode && siteMapOpen);
  els.appShell?.classList.toggle("calendar-focus", calendarOpen);
  els.appShell?.classList.toggle("site-map-focus", siteMapOpen);
  els.appShell?.classList.toggle("site-map-fullscreen", siteMapFullScreenActive);
  els.appShell?.classList.toggle("site-map-monitor", siteMapMonitorActive);
  document.body?.classList.toggle("site-map-fullscreen-active", siteMapFullScreenActive);
  document.body?.classList.toggle("site-map-monitor-active", siteMapMonitorActive);
}

function restoreMobileDashboardAfterSiteMapClose() {
  if (!window.matchMedia("(max-width: 760px)").matches) return;
  if (currentRole === "Customer") return;
  els.dashboardPanel?.classList.remove("hidden");
  renderDashboard();
  window.requestAnimationFrame(() => {
    els.dashboardPanel?.classList.remove("hidden");
  });
}

