function isPdfFile(file) {
  return Boolean(file && (file.type === "application/pdf" || file.name?.toLowerCase().endsWith(".pdf")));
}

async function readSiteMapFile(file) {
  if (!file) return null;
  if (isPdfFile(file)) {
    return renderSiteMapPdf(file);
  }
  if (!file.type.startsWith("image/")) {
    throw new Error("Please choose a PNG, JPG, or PDF site map.");
  }
  const rawDataUrl = await fileToDataUrl(file);
  const dataUrl = await resizePhotoDataUrl(rawDataUrl, 3200, 0.88);
  return storeSiteMapImageFile(file, dataUrl);
}

async function renderSiteMapPdf(file) {
  const pdfjs = window.pdfjsLib;
  if (!pdfjs?.getDocument) {
    throw new Error("PDF support is still loading. Wait a moment, then choose the PDF again.");
  }
  pdfjs.GlobalWorkerOptions.workerSrc = pdfjs.GlobalWorkerOptions.workerSrc || "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js";
  const data = await fileToArrayBuffer(file);
  const pdfDocument = await pdfjs.getDocument({ data }).promise;
  const page = await pdfDocument.getPage(1);
  const baseViewport = page.getViewport({ scale: 1 });
  const scale = Math.min(4, Math.max(2, 3200 / Math.max(baseViewport.width, baseViewport.height)));
  const viewport = page.getViewport({ scale });
  const canvas = document.createElement("canvas");
  canvas.width = Math.ceil(viewport.width);
  canvas.height = Math.ceil(viewport.height);
  const context = canvas.getContext("2d", { alpha: false });
  context.fillStyle = "#ffffff";
  context.fillRect(0, 0, canvas.width, canvas.height);
  await page.render({ canvasContext: context, viewport }).promise;
  const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
  return storeSiteMapImageFile(new File([dataUrlToBlob(dataUrl)], replaceFileExtension(file.name || "site-map.pdf", "jpg"), { type: "image/jpeg" }), dataUrl, file.name);
}

async function storeSiteMapImageFile(file, dataUrl, sourceName = "") {
  const blob = dataUrlToBlob(dataUrl);
  const uploadFile = new File([blob], replaceFileExtension(file.name || "site-map.jpg", "jpg"), { type: "image/jpeg" });
  const stored = await uploadFileToServerStorage(uploadFile, "site-maps");
  return stored ? {
    ...stored,
    originalName: sourceName || file.name,
    storageStatus: "cloud",
    cloudReady: true
  } : {
    name: uploadFile.name,
    originalName: sourceName || file.name,
    type: "image/jpeg",
    dataUrl,
    storageStatus: "local",
    cloudReady: false
  };
}

function siteMapImageIsCloudReady(image) {
  return Boolean(image?.cloudReady || image?.path || image?.storageKey || image?.storage_key || image?.url || image?.publicUrl || image?.public_url);
}

async function readDocumentFile(file, expectedType) {
  if (!file) return null;
  const isPdf = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");
  if (expectedType === "application/pdf" && !isPdf) {
    alert("Please choose a PDF file.");
    return null;
  }
  const stored = await uploadFileToServerStorage(file, "manuals");
  if (stored) {
    return stored;
  }
  if (file.size > 4 * 1024 * 1024) {
    alert("That PDF could not be uploaded to SiteWorks server storage and is too large for browser storage. Try a smaller PDF, then try again.");
    return null;
  }
  const dataUrl = await fileToDataUrl(file);
  return { name: file.name, type: file.type || expectedType || "application/octet-stream", dataUrl };
}

async function storeResizedPhotoFile(file, dataUrl, folder) {
  const blob = dataUrlToBlob(dataUrl);
  const uploadFile = new File([blob], replaceFileExtension(file.name || "photo.jpg", "jpg"), { type: "image/jpeg" });
  const stored = await uploadFileToServerStorage(uploadFile, folder);
  return stored || { name: file.name, type: "image/jpeg", dataUrl };
}

async function uploadFileToServerStorage(file, folder = "uploads") {
  if (!file) return null;
  try {
    return await siteworksApi.uploadFile(file, folder, getSavedAuthSession());
  } catch (error) {
    console.warn("SiteWorks server storage upload skipped.", error);
    return null;
  }
}

function dataUrlToBlob(dataUrl) {
  const [header, payload] = String(dataUrl || "").split(",");
  const mime = /data:([^;]+)/.exec(header || "")?.[1] || "application/octet-stream";
  const binary = atob(payload || "");
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return new Blob([bytes], { type: mime });
}

function replaceFileExtension(name, extension) {
  const cleanName = String(name || "file").replace(/\.[^.]+$/, "");
  return `${cleanName}.${extension}`;
}

function slugifyStoragePath(value) {
  return String(value || "file")
    .trim()
    .replace(/[^a-z0-9._/-]+/gi, "-")
    .replace(/-+/g, "-")
    .replace(/^[-/]+|[-/]+$/g, "")
    .toLowerCase() || "file";
}

function mediaSource(file) {
  if (!file) return "";
  const signedUrl = signedMediaSource(file);
  return signedUrl || file.url || file.publicUrl || file.public_url || file.dataUrl || "";
}

function cloudMediaSource(file) {
  return file?.url || file?.publicUrl || file?.public_url || "";
}

function hasMedia(file) {
  return Boolean(mediaSource(file));
}

function signedMediaKey(file) {
  const path = getServerStoragePath(file);
  if (!path) return "";
  return `${file.bucket || file.storageBucket || "local"}:${path}`;
}

function signedMediaSource(file) {
  const key = signedMediaKey(file);
  if (!key) return "";
  const failedAt = signedMediaUrlFailures.get(key);
  if (failedAt && failedAt > Date.now() - 10 * 60 * 1000) return "";
  const cached = signedMediaUrlCache.get(key);
  if (cached && cached.expiresAt > Date.now() + 30 * 1000) return cached.url;
  requestSignedMediaUrl(file, key);
  return cached?.url || "";
}

function requestSignedMediaUrl(file, key = signedMediaKey(file)) {
  if (!key || signedMediaUrlPending.has(key)) return;
  signedMediaUrlPending.add(key);
  const request = siteworksServerEnabled()
    ? siteworksApi.getSignedFileUrl(file)
    : Promise.resolve(null);
  request
    .then(async (response) => {
      if (!response?.ok) {
        signedMediaUrlFailures.set(key, Date.now());
        return;
      }
      const data = await response.json();
      const signedUrl = data?.signedUrl || data?.signedURL;
      if (!signedUrl) {
        signedMediaUrlFailures.set(key, Date.now());
        return;
      }
      signedMediaUrlFailures.delete(key);
      signedMediaUrlCache.set(key, {
        url: signedUrl,
        expiresAt: Date.now() + Number(data.expiresIn || 600) * 1000
      });
      window.setTimeout(render, 0);
    })
    .catch((error) => console.warn("Signed file link skipped.", error))
    .finally(() => signedMediaUrlPending.delete(key));
}

function getServerStoragePath(file) {
  const directPath = file?.storageKey || file?.storage_key || file?.path || "";
  if (directPath) return directPath;
  const url = String(file?.url || file?.publicUrl || file?.public_url || "");
  const marker = `/storage/v1/object/public/${LEGACY_STORAGE_BUCKET}/`;
  const authenticatedMarker = `/storage/v1/object/authenticated/${LEGACY_STORAGE_BUCKET}/`;
  const markerIndex = url.indexOf(marker);
  const authenticatedIndex = url.indexOf(authenticatedMarker);
  const encodedPath = markerIndex >= 0
    ? url.slice(markerIndex + marker.length)
    : authenticatedIndex >= 0
      ? url.slice(authenticatedIndex + authenticatedMarker.length)
      : "";
  if (!encodedPath) return "";
  try {
    return decodeURIComponent(encodedPath.split(/[?#]/)[0]);
  } catch {
    return encodedPath.split(/[?#]/)[0];
  }
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function fileToArrayBuffer(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
}

function resizePhotoDataUrl(dataUrl, maxSize, quality) {
  return new Promise((resolve) => {
    const image = new Image();
    image.onload = () => {
      const scale = Math.min(1, maxSize / Math.max(image.width, image.height));
      const width = Math.max(1, Math.round(image.width * scale));
      const height = Math.max(1, Math.round(image.height * scale));
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d");
      context.fillStyle = "#ffffff";
      context.fillRect(0, 0, width, height);
      context.drawImage(image, 0, 0, width, height);
      resolve(canvas.toDataURL("image/jpeg", quality));
    };
    image.onerror = () => resolve(dataUrl);
    image.src = dataUrl;
  });
}

function downloadCsv(asset) {
  const customer = getCustomer(asset.customerId);
  const locationRecord = getLocation(asset.locationId);
  const rows = [
    ["Customer", "Location", "Asset", "Completed At", "Technician", "Result", "Reading", "Checks", "Notes", "Photo"],
    ...asset.history.map((item) => [
      customer?.name || "",
      locationRecord?.name || "",
      asset.name,
      item.completedAt,
      item.technician,
      item.result,
      item.reading,
      item.completedChecks.join("; "),
      item.notes,
      item.photo?.name || ""
    ])
  ];
  const csv = rows.map((row) => row.map(csvCell).join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `${asset.name.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}-history.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

